# ---- CLI 骨架（关键字待现场用 ? 确认）----
enable
configure terminal
interface aggregate {{agg_name}}
 member eth{{member1_no}} eth{{member2_no}}
 mode {{lacp_mode}}
 exit
interface aggregate {{agg_name}}.{{vlan_id}}
 ip address {{agg_ip}} {{agg_mask}}
 exit
exit
write
show interface aggregate
